// Decide a quién le toca seguimiento hoy y cuál de los tres mensajes.
//
// Reglas del playbook que se codifican acá:
//  · Máximo 3 seguimientos. Después se para. Insistir más no vende y sí
//    hace que te reporten — y una cuenta de WhatsApp bloqueada es cero
//    ventas por ese canal hasta resolverlo.
//  · Un seguimiento por lead por día. Nunca dos el mismo día.
//  · Nada a leads ya cerrados o marcados como perdidos.
//  · Nada si la fecha de check-in ya pasó.

const DIAS = { 'FU-24': 1, 'FU-72': 3, 'FU-7D': 7 };

const hoy = new Date();
const hoyISO = hoy.toISOString().slice(0, 10);
const diasEntre = (a, b) => Math.floor((b - a) / 86400000);

const salida = [];

for (const lead of $input.all().map((i) => i.json)) {
  const estado = (lead.estado || '').toLowerCase();

  // Cerrado, perdido o sin teléfono: no se toca.
  if (['reservado', 'cerrado', 'perdido', 'no_contactar'].includes(estado)) continue;
  if (!lead.telefono) continue;

  const enviados = Number(lead.seguimientos_enviados || 0);
  if (enviados >= 3) continue;

  // Uno por día como máximo.
  if ((lead.ultimo_seguimiento || '').slice(0, 10) === hoyISO) continue;

  const creado = new Date(lead.fecha);
  if (isNaN(creado)) continue;
  const antiguedad = diasEntre(creado, hoy);

  // Si ya pasó el check-in que pidió, el seguimiento no tiene sentido.
  if (lead.check_in && lead.check_in < hoyISO) continue;

  let plantilla = null;
  if (enviados === 0 && antiguedad >= DIAS['FU-24']) plantilla = 'FU-24';
  else if (enviados === 1 && antiguedad >= DIAS['FU-72']) plantilla = 'FU-72';
  else if (enviados === 2 && antiguedad >= DIAS['FU-7D']) plantilla = 'FU-7D';

  if (!plantilla) continue;

  salida.push({
    json: {
      rowNumber: lead.row_number ?? lead.__rowNum__,
      telefono: lead.telefono,
      nombre: (lead.nombre || '').split(' ')[0],
      checkIn: lead.check_in || '',
      checkOut: lead.check_out || '',
      totalCotizado: lead.total_cotizado || '',
      plantilla,
      seguimientosEnviados: enviados + 1,
      hoyISO,
    },
  });
}

return salida;

// Redacta según la plantilla que tocó. Cada seguimiento trae algo nuevo:
// un "¿pudiste ver?" no aporta nada y se ignora.

const d = $json;
const nombre = d.nombre || '';
const saludo = nombre ? `¡Hola ${nombre}!` : '¡Hola!';
const total = d.totalCotizado ? `$${d.totalCotizado}` : 'la tarifa que te pasé';

let texto;

switch (d.plantilla) {
  case 'FU-24':
    // Corto, sin descuento. Todavía no toca ceder precio.
    texto = `${saludo} Te escribo por las fechas que me consultaste 🌊\n\n` +
      `Todavía te puedo sostener ${total}. ¿La dejamos apartada?`;
    break;

  case 'FU-72':
    // Ángulo nuevo, no repetir la misma oferta.
    texto = `${nombre ? nombre + ', ' : ''}te cuento que entre semana está bastante ` +
      `más tranquilo y sale mejor de precio 🌊\n\n` +
      `Si tenés flexibilidad de fechas, decime y te paso opciones. ` +
      `Kayaks, snorkel y desayuno van incluidos igual.`;
    break;

  case 'FU-7D':
    // Última. Acá sí se cede, y en valor (costo casi cero) antes que en tarifa.
    texto = `${nombre ? nombre + ', ' : ''}última que te escribo por esto 🙌\n\n` +
      `Si te decidís esta semana, te dejo ${total} y te sumo el late check-out ` +
      `sin cargo — así el último día aprovechás la playa completa.\n\n` +
      `Cualquier cosa quedo por acá.`;
    break;

  default:
    return [];
}

return [{ json: { ...d, texto } }];
